def decision(prompt,labels,correct=0):
    return {'mechanic':'decision','prompt':prompt,'config':{'choices':items(labels),'key':[str(correct)]}}

def order(prompt,labels):
    cards=items(labels)
    return {'mechanic':'order','prompt':prompt,'config':{'choices':cards[2:]+cards[:2], 'length':len(cards),'key':[str(i) for i in range(len(cards))]}}

def pattern(prompt,sequence,labels,correct=0):
    return decision(prompt+' '+sequence,labels,correct)

