def make_set(level,ages):
    per=4+level*2;tasks=[]
    names={'technical':'собирать модели и разбираться в технике','natural':'исследовать природу и проводить опыты','art':'придумывать образы и создавать творческие работы','social':'общаться, рассказывать и работать в команде','sport':'двигаться, тренироваться и играть в команде'}
    for direction in DIRECTIONS:
        preference={'mechanic':'preference','prompt':('Хочешь '+names[direction]+'?'),'config':{'choices':items(['Да, хочу','Можно попробовать','Пока не хочется']),'preference_weights':[1,.5,0]}}
        pool=activities(level,direction)
        chosen=[preference]+pool[:per-1]
        for n,task in enumerate(chosen):
            # Rotate candidate order while retaining explicit IDs and the scoring key.
            task={**task,'config':dict(task['config'])}
            if 'choices' in task['config'] and task['mechanic']!='order':
                choices=task['config']['choices'];shift=(len(tasks)+level)%len(choices)
                task['config']['choices']=choices[shift:]+choices[:shift]
            tasks.append({**task,'id':f'v2-{direction}-{n+1}','category':'logic' if direction=='technical' else direction,'direction':direction,'stimulus':'','options':[]})
    assert len(tasks)==[20,30,40,50][level]
    return {'id':str(uuid5(NAMESPACE_URL,f'liga/discovery/{ages[0]}-{ages[1]}/2')),'code':f'discovery-{ages[0]}-{ages[1]}','version':'2.0.0','tasks':tasks}

SETS={f'{a}-{b}':make_set(i,(a,b)) for i,(a,b) in enumerate(GROUPS)}

def evaluate(tasks,answers):
    from .journey_assessment import score_task
    groups={k:[] for k in DIRECTIONS};preferences={k:0 for k in DIRECTIONS};details=[]
    for task in tasks:
        raw=answers[task['id']];direction=task['direction']
        if task['mechanic']=='preference':
            preferences[direction]=task['config']['preference_weights'][int(raw['selected'][0])];value=None
        else:
            value=score_task(task,raw)
            # Multi-step plans are scored as a whole to avoid rewarding incoherent fragments.
            if task['mechanic']=='order':value={'correct':int(value['correct']==value['total']),'total':1}
            groups[direction].append(value['correct']/value['total'])
        details.append({'task_id':task['id'],'prompt':task['prompt'],'metric':direction,'score':value})
    performance={k:round(sum(v)/len(v)*100,1) for k,v in groups.items()}
    affinities={k:round(performance[k]*.85+preferences[k]*15,1) for k in DIRECTIONS}
    ranked=sorted(DIRECTIONS,key=lambda k:(-affinities[k],-preferences[k],k))
    eligible=[k for k in ranked if performance[k]>=60 and affinities[k]>=70]
    main=eligible[:1];alternatives=[k for k in ranked if k not in main and performance[k]>=60 and affinities[k]>=60 and main and affinities[k]>=affinities[main[0]]-15][:2]
    def item(k):return {'code':k,'name':DIRECTIONS[k],'reason':f"Выполнение заданий направления: {performance[k]}%. "+('Есть интерес к этим занятиям.' if preferences[k] else '')}
    fallback=['art'] if not main and preferences['art']>=.5 else []
    support=[{'code':k,'name':DIRECTIONS[k],'message':'Попробуйте ещё раз разобрать задания этого направления без спешки.'} for k in ranked if performance[k]<60]
    return {'completed':len(answers),'total':len(tasks),'correct':sum((d['score'] or {}).get('correct',0) for d in details),'test_name':'Возрастной маршрут','test_code':'discovery','scored':False,'comment':'',
            'task_details':details,'performance':performance,'preferences':preferences,'affinities':affinities,'directions':[item(k) for k in main], 'alternatives':[item(k) for k in alternatives], 'exploratory':[item(k) for k in fallback],'support':support,'recommended_codes':main+alternatives+fallback,'selection_version':'thresholds-1.0.0'}
